input.command:
cat > /tmp/edit_review.js <<'EOF'
const fs=require('fs');const p='Tools/Blender/shotgun_render_review.py';let s=fs.readFileSync(p,'utf8');
const a=`sc = bpy.context.scene
sc.render.engine = "CYCLES"`;
const b=`    # Tripo exported the gun turned about the vertical axis. Turn it back: the angle that makes it narrowest.
    import numpy as np
    ob = [o for o in bpy.data.objects if o.type == "MESH"][0]
    xy = np.array([(ob.matrix_world @ v.co)[:2] for v in ob.data.vertices])
    best = min((np.ptp(xy[:, 0] * math.cos(a) - xy[:, 1] * math.sin(a)), a)
               for a in np.radians(np.arange(-25, 25, 0.05)))
    ob.rotation_euler.z += best[1]
    bpy.context.view_layer.update()
    xs = [(ob.matrix_world @ v.co).x for v in ob.data.vertices]
    ob.location.x -= (min(xs) + max(xs)) / 2
    bpy.context.view_layer.update()
    print("STRAIGHTEN yaw_deg", round(math.degrees(best[1]), 2), "width_m", round(float(best[0]), 4))

sc = bpy.context.scene
sc.render.engine = "CYCLES"`;
if(!s.includes(a))throw 1; s=s.split(a).join(b);
const c=`FP = {}`;
const d=`# Shooter looks to -Y; the shooter's right is -X. Hand point (grip top) is about (0, 0.12, 0.165).
# fp: eye 9 cm left of the gun, 13 cm above the grip top, 23 cm behind it; 90 deg horizontal FOV (18 mm).
FP = {
    "fp": ((0.09, 0.35, 0.30), (0.09, -1.0, 0.27), 18),
    "fp_close": ((0.105, 0.26, 0.32), (0.0, -0.12, 0.21), 35),
    "fp_sight": ((0.07, 0.30, 0.34), (0.0, 0.08, 0.31), 70),
    "fp_screen": ((0.16, 0.16, 0.30), (0.04, -0.10, 0.20), 60),
    "left_receiver": ((0.34, 0.06, 0.24), (0.0, -0.06, 0.20), 50),
    "left_front": ((0.34, -0.22, 0.24), (0.0, -0.32, 0.17), 50),
    "left_stock": ((0.40, 0.36, 0.22), (0.0, 0.30, 0.17), 50),
}`;
if(!s.includes(c))throw 2; s=s.split(c).join(d);
fs.writeFileSync(p,s);
EOF
