input.command:
cat > /tmp/edit_day.js <<'EOF'
const fs=require('fs');const p='Devlog/days/2026-11-12.md';let s=fs.readFileSync(p,'utf8');
const nl=s.includes('\r\n')?'\r\n':'\n';
const lines=s.split(nl);
const i=lines.findIndex(l=>l.startsWith('- `media/2026-11-12/16a_pistol_reload_beats.png`'));
if(i<0)throw 1;
lines.splice(i+1,0,'- `media/2026-11-12/17a_shotgun_source_first_person.png`, `17b_shotgun_source_close.png`, `17c_shotgun_source_left.png`, `17d_shotgun_source_screen.png` (twenty-sixth block; Blender Cycles renders, not the game): the shotgun\'s Tripo source untouched, from the player\'s camera, close up, from the left, and its side screen.');
fs.writeFileSync(p,lines.join(nl));
EOF
node /tmp/edit_day.js && git add Tools/Blender/shotgun_inspect.py Tools/Blender/shotgun_render_review.py Glyphbound/SourceArt/Weapons/Shotgun/README.md Devlog/days/2026-11-12.md Devlog/media/2026-11-12/17a_shotgun_source_first_person.png Devlog/media/2026-11-12/17b_shotgun_source_close.png Devlog/media/2026-11-12/17c_shotgun_source_left.png Devlog/media/2026-11-12/17d_shotgun_source_screen.png && git diff --cached --stat && git commit -q -F - <<'EOF'
Shotgun source inspected (owner: the Tripo zip and the shotgun handoff): one FBX of 20,957 triangles turned 11.3 degrees, one 2048 colour JPG and no PBR maps; inspect and review-render scripts, four renders of the untouched source from the player's camera, the source README, and the day entry's block with the provisional choices (cell as magazine, sliding forend, hologram in the sight window)

