// One-off: records the shotgun decisions in the GDD and the GLB analysis in the day entry. Run from C:\GameJam.
const fs = require('fs');
function edit(p, fn) {
  const raw = fs.readFileSync(p, 'utf8');
  const nl = raw.includes('\r\n') ? '\r\n' : '\n';
  let s = raw.split('\r\n').join('\n');
  s = fn(s, (a, b) => { if (!s.includes(a)) throw new Error('not found in ' + p + ': ' + a.slice(0, 60)); s = s.split(a).join(b); return s; });
