const rep = (a, b) => { if (!s.includes(a)) throw new Error('not found: ' + a.slice(0, 70)); s = s.split(a).join(b); };

rep(`CELL_AXIS_Z, CELL_RADIUS, CELL_SKIN = 0.138, 0.034, 0.008
`, `CELL_SKIN = 0.0035         # metres from the fitted cylinder that still count as the cell
