          (lit.sum(), " ".join("%.1f" % (v_ * 1000) for v_ in np.percentile(radial[lit], (10, 50, 90))),
           " ".join("%.4f" % v_ for v_ in np.percentile(pos[..., 1][lit], (2, 98)))))
cell = in_cell_box & (np.abs(radial - CELL_RADIUS) < CELL_SKIN) & (pos[..., 1] > CELL_Y[0]) & (pos[..., 1] < CELL_Y[1])`,
