rep(`EXTRAS = build_extras()  # in the scene before the bakes`,`if stage == "bay":
    # Measures, on the welded body alone: the bay the cell sits in, and the side slabs that carry the screens.
    from mathutils.bvhtree import BVHTree
    bvh = BVHTree.FromObject(SRC, bpy.context.evaluated_depsgraph_get())

    def hit(origin, direction, axis):
        h_ = bvh.ray_cast(Vector(origin), Vector(direction))
        return None if h_[0] is None else h_[0][axis] * 1000

    def row(label, values):
        print("%-10s %s" % (label, " ".join("  --- " if v_ is None else "%6.1f" % v_ for v_ in values)))

    ys = [y_ / 1000 for y_ in range(-245, -104, 10)]
    zs = [z_ / 1000 for z_ in range(90, 201, 8)]
    for name_, ox, dx in (("BAY from the left (+X): x", 1.0, -1), ("BAY from the right (-X): x", -1.0, 1)):
        print(name_, "; rows z, columns y =", " ".join("%6d" % (y_ * 1000) for y_ in ys))
        for z_ in reversed(zs):
            row("z=%d" % (z_ * 1000), [hit((ox, y_, z_), (dx, 0, 0), 0) for y_ in ys])
    xs = [x_ / 1000 for x_ in range(-48, 49, 8)]
    print("BAY from below: z ; rows y, columns x =", " ".join("%6d" % (x_ * 1000) for x_ in xs))
    for y_ in ys:
        row("y=%d" % (y_ * 1000), [hit((x_, y_, -1.0), (0, 0, 1), 2) for x_ in xs])
    print("BAY looking forward from y=-0.176 (the forend's rear wall): y ; rows z, columns x")
    for z_ in reversed(zs):
        row("z=%d" % (z_ * 1000), [hit((x_, -0.176, z_), (0, -1, 0), 1) for x_ in xs])
    print("BAY looking back from y=-0.176 (the receiver's front wall): y ; rows z, columns x")
    for z_ in reversed(zs):
        row("z=%d" % (z_ * 1000), [hit((x_, -0.176, z_), (0, 1, 0), 1) for x_ in xs])
    ys = [y_ / 1000 for y_ in range(-135, 6, 10)]
    zs = [z_ / 1000 for z_ in range(88, 225, 8)]
    for name_, ox, dx in (("SCREEN slab from the left (+X): x", 1.0, -1), ("SCREEN slab from the right (-X): x", -1.0, 1)):
        print(name_, "; rows z, columns y =", " ".join("%6d" % (y_ * 1000) for y_ in ys))
        for z_ in reversed(zs):
            row("z=%d" % (z_ * 1000), [hit((ox, y_, z_), (dx, 0, 0), 0) for y_ in ys])
    sys.exit(0)

EXTRAS = build_extras()  # in the scene before the bakes`);
