const fs = require('fs');
function edit(p, fn) {
  const raw = fs.readFileSync(p, 'utf8');
  const nl = raw.includes('\r\n') ? '\r\n' : '\n';
  let s = raw.split('\r\n').join('\n');
  const rep = (a, b) => { if (!s.includes(a)) throw new Error('not found in ' + p + ': ' + a.slice(0, 60)); s = s.split(a).join(b); };
  fn(rep, () => s, v => { s = v; });
  fs.writeFileSync(p, s.split('\n').join(nl));
}

