const fs = require('fs');
const p = 'Tools/Blender/shotgun_build_blend.py';
let s = fs.readFileSync(p, 'utf8').split('\r\n').join('\n');
const rep = (a, b) => { if (!s.includes(a)) throw new Error('not found: ' + a.slice(0, 70)); s = s.split(a).join(b); };

