// One-off: derives Tools/Jam/import_shotgun.py and Import-Shotgun.ps1 from the rifle's and applies the shotgun's
// differences. Run from C:\GameJam.
const fs = require('fs');
let s = fs.readFileSync('Tools/Jam/import_rifle.py', 'utf8').split('\r\n').join('\n');
const rep = (a, b) => { if (!s.includes(a)) throw new Error('not found: ' + a.slice(0, 70)); s = s.split(a).join(b); };
const cut = (from, to, repl) => { const i = s.indexOf(from), j = s.indexOf(to, i + from.length); if (i < 0 || j < 0) throw new Error('cut: ' + from.slice(0, 50)); s = s.slice(0, i) + repl + s.slice(j); };

