rep('MESHES = ["SM_Rifle_Body", "SM_Rifle_Trigger", "SM_Rifle_Magazine", "SM_Rifle_WeakPointLight", "SM_Rifle_AmmoDisplay"]',
    'MESHES = ["SM_Shotgun_Body", "SM_Shotgun_Trigger", "SM_Shotgun_Pump", "SM_Shotgun_Magazine", "SM_Shotgun_WeakPointLight",\n          "SM_Shotgun_AmmoDisplay"]');
s = s.split('T_Rifle_').join('T_Shotgun_');
rep('RIFLE_MINT = (0.05, 0.9, 0.6)', 'SHOTGUN_CYAN = (0.10, 0.85, 1.00)');
