`);
rep('fail("missing %s (run Tools/Blender/rifle_export_fbx.py)" % source)', 'fail("missing %s (run Tools/Blender/shotgun_export_fbx.py)" % source)');
rep('    # One-sided on purpose: two-sided, the rifle looked grainy (tried, seen in the smoke screenshot).',
