54	
55		virtual void OnUnequipped() override;
56	
57		virtual bool UsesAmmo() const override { return true; }
58		virtual FGBAmmoState GetAmmo() const override { return Ammo; }
59		virtual void SetAmmo(const FGBAmmoState& InAmmo) override;
60		virtual void RefillAmmo() override;
61		virtual int32 AddSpareMagazines(int32 Count) override;
62		virtual bool IsReloading() const override { return bReloading; }
63		virtual bool IsAiming() const override { return bAiming; }
64		virtual float GetReloadProgress() const override;
65	
66		int32 GetMagazineSize() const;
67		/** Spread half-angle in degrees right now: hip or aim, plus the moving bonus (GDD 4). Shots and crosshair use it. */
68		float GetCurrentSpread() const;
69		int32 GetMaxSpareMagazines() const;
70	
71		/** True when the real model meshes were built (Definition.ViewModel names a model and all its meshes loaded). */
72		bool HasViewModel() const { return bViewModel; }
73		/** Parts with a loaded mesh of the model (pistol 6, rifle 5). */
74		int32 GetViewModelMeshCount() const;
75		/** Dynamic materials made for the model's parts (the body alone has many slots). */
76		int32 GetViewModelMIDCount() const { return ViewModelMIDs.Num(); }
77		/** Distance in cm of the magazine from its rest location, in the body's frame. */
78		float GetViewModelMagazineOffsetCm() const;
