108		void SetReloadPreview(float Progress);
109		/** Dev only: releases the pin; the gun blends back to rest. */
110		void ClearReloadPreview();
111	
112	protected:
113		virtual bool AcceptsEnchant() const override { return true; }
114		virtual bool PerformAttack() override;
115	
116		void FireHitscan(const FGBDamageInfo& BaseInfo, float SpreadDegrees);
117		void FireProjectile(const FGBDamageInfo& BaseInfo, float SpreadDegrees);
118		void CancelReload();
