1	// Guns (GDD 8): cyberpunk, 3D placeholder viewmodel. Shoot, aim, reload, magazines; the weapon enchant applies.
2	#pragma once
3	
4	#include "CoreMinimal.h"
5	#include "Core/GBPlaceholder.h"
6	#include "Weapons/GBHeldItem.h"
7	#include "GBGun.generated.h"
8	
9	class UStaticMeshComponent;
10	class UMaterialInstanceDynamic;
11	class UCanvas;
12	class UCanvasRenderTarget2D;
13	struct FGBDamageInfo;
14	struct FGBGunModelArt;
15	
16	/** Reload animation shared by the gun viewmodel and the HUD hands: everything is a function of the reload progress (0 to 1). */
17	namespace GBReloadAnim
18	{
19		/** Where the 2D left hand is, as three 0..1 amounts: Reach (towards the magazine well), Drop (off the bottom of the screen) and Push (the seat bump). */
20		struct FHandBeat
21		{
22			float Reach = 0.f;
23			float Drop = 0.f;
24			float Push = 0.f;
25		};
26		/** Zero beats for a negative progress (no reload animation running). */
27		FHandBeat HandBeat(float Progress);
28		/** 0..1: how far the gun is in its reload pose (eases in over the first beat, out over the last). 0 for a negative progress. */
29		float PoseAmount(float Progress);
30	}
31	
32	/**
33	 * Every number through GetStat: Damage, FireInterval, MagazineSize, SpareMagazines, ReloadTime, Range, Spread,
34	 * AimSpread, RecoilPitch, RecoilYaw, RecoilRecovery, Pellets, Falloff*, HeadshotMult, AimFOV, AimMoveSpeedMult,
35	 * AimTime, EnchantBuildUpMult, and ProjectileSpeed / ProjectileRadius / ProjectileGravity for FireMode "Projectile".
36	 * Reload: consumes one spare magazine, fills the magazine; the rounds left in the old one are lost
37	 * (provisional, classic tactical style). Switching weapon cancels it.
38	 */
39	UCLASS()
40	class GLYPHBOUND_API AGBGun : public AGBHeldItem
41	{
42		GENERATED_BODY()
43	
44	public:
45		virtual void InitFromDefinition(const FGBWeaponDefinition& Definition, AGBPlayerCharacter* InOwner) override;
46		virtual void Tick(float DeltaSeconds) override;
47		virtual void EndPlay(const EEndPlayReason::Type EndPlayReason) override;
48	
49		virtual void StartPrimary() override { PressTrigger(); }
50		virtual void StopPrimary() override { ReleaseTrigger(); }
51		virtual void StartSecondary() override;
52		virtual void StopSecondary() override;
53		virtual void Reload() override;
54	
55		virtual void OnUnequipped() override;
56	
57		virtual bool UsesAmmo() const override { return true; }
58		virtual FGBAmmoState GetAmmo() const override { return Ammo; }
59		virtual void SetAmmo(const FGBAmmoState& InAmmo) override;
60		virtual void RefillAmmo() override;
61		virtual int32 AddSpareMagazines(int32 Count) override;
62		virtual bool IsReloading() const override { return bReloading; }
63		virtual bool IsAiming() const override { return bAiming; }
64		virtual float GetReloadProgress() const override;
65	
66		int32 GetMagazineSize() const;
67		/** Spread half-angle in degrees right now: hip or aim, plus the moving bonus (GDD 4). Shots and crosshair use it. */
68		float GetCurrentSpread() const;
69		int32 GetMaxSpareMagazines() const;
70	
71		/** True when the real model meshes were built (Definition.ViewModel names a model and all its meshes loaded). */
72		bool HasViewModel() const { return bViewModel; }
73		/** Parts with a loaded mesh of the model (pistol 6, rifle 5). */
74		int32 GetViewModelMeshCount() const;
75		/** Dynamic materials made for the model's parts (the body alone has many slots). */
76		int32 GetViewModelMIDCount() const { return ViewModelMIDs.Num(); }
77		/** Distance in cm of the magazine from its rest location, in the body's frame. */
78		float GetViewModelMagazineOffsetCm() const;
79		/** Element whose color is currently sent to the model materials (only meaningful when enchanted). */
80		EGBElement GetViewModelGlowElement() const { return LastGlowElement; }
81		/** Whether the model glow currently comes from the weapon enchant. */
82		bool IsViewModelGlowEnchanted() const { return bLastGlowEnchanted; }
83		/** Last ImbueRemaining value sent to the model materials. */
84		float GetViewModelImbueSent() const { return LastImbueSent; }
85		/** Whether the energy bar is in its last-seconds blink (the enchant is about to end). The value sent is 0 in the dark half of each blink. */
86		bool IsViewModelEnergyBarBlinking() const { return bEnergyBarBlinking; }
87		/** Text currently drawn on the holographic ammo display (rounds in the magazine, "--" while reloading). */
88		const FString& GetViewModelDisplayText() const { return ShownDisplayText; }
89		/** Last Flash value sent to the weak-point light (0 = off, 1 = full glow). */
90		float GetViewModelWeakPointFlash() const { return LastFlashSent; }
91		/** Whether the muzzle flash shape is showing right now. */
92		bool IsMuzzleFlashVisible() const;
93		/** How far back in cm the shot kick has pushed the viewmodel right now (0 at rest). */
94		float GetViewModelKickBackCm() const { return CurrentKickBackCm; }
95		/** Whether the magazine mesh is showing (it is hidden while the old one is gone and the new one has not arrived). */
96		bool IsViewModelMagazineVisible() const;
97		/** Distance in cm of the viewmodel root from its rest location (reload pose and shot kick both move it). */
98		float GetViewModelRootOffsetCm() const;
99		/** Angle in degrees between the viewmodel root's rotation and its rest rotation. */
100		float GetViewModelRootAngleDeg() const;
101		/** Per-model art value for the HUD: how far (sprite pixels, x right, y down) the left hand moves to meet the magazine. */
102		FVector2D GetReloadHandReach() const;
103		/** Per-model art value for the HUD: how far (sprite pixels) the right hand moves at full pose so it stays on the grip. */
104		FVector2D GetReloadRightHandFollow() const;
105		/** Progress (0 to 1) the reload animation is showing: the pinned preview if any, else the real reload; -1 when none. */
106		float GetReloadAnimProgress() const;
107		/** Dev only (smoke run): pins the reload animation at this progress without touching ammo or the reload itself. */
108		void SetReloadPreview(float Progress);
109		/** Dev only: releases the pin; the gun blends back to rest. */
110		void ClearReloadPreview();
111	
112	protected:
113		virtual bool AcceptsEnchant() const override { return true; }
114		virtual bool PerformAttack() override;
115	
116		void FireHitscan(const FGBDamageInfo& BaseInfo, float SpreadDegrees);
117		void FireProjectile(const FGBDamageInfo& BaseInfo, float SpreadDegrees);
118		void CancelReload();
119		void FinishReload();
120		void SetAiming(bool bInAiming);
121		/** Moves the FOV towards the aim target; snaps back to the hip FOV when bInstant. */
122		void UpdateAimFOV(float DeltaSeconds, bool bInstant);
123		void BuildViewModel(const FGBWeaponDefinition& Definition);
124		void BuildPlaceholderViewModel(const FGBWeaponDefinition& Definition);
125		UStaticMeshComponent* AddPart(FName Name, EGBShape Shape, const FVector& Location, const FVector& Size, const FLinearColor& Color, bool bGlow);
126	
127		/** Loads the model's SM_* meshes and attaches them. False when any mesh is missing (caller falls back to placeholders). */
128		bool TryBuildViewModel(const FGBGunModelArt& Art);
129		/** Trigger pull, magazine slide, glow color, weak-point light, ammo text, kick and muzzle flash, only while the viewmodel exists. */
130		void UpdateViewModel(float DeltaSeconds);
131		/** Starts the shot kick and the muzzle flash. */
132		void StartShotEffects();
133		/** The one place that writes the viewmodel root's transform: rest pose + reload pose + shot kick. */
134		void ApplyViewModelPose();
135		/** Places the magazine (slide, fall on screen, hidden, rise, slide in) from the reload animation progress. */
136		void ApplyReloadMagazine();
137		/** Starts the short blend from the current reload pose back to rest (a cancelled reload or a released preview). */
138		void BeginReloadBlend();
139		/** Magazine at rest and visible, pose at rest, no blend: used when the gun leaves the hand. */
140		void ResetReloadVisuals();
141		void HideMuzzleFlash();
142		/** Global damage event: a weak-point hit by this gun's owner while this gun is equipped lights the weak-point light. */
143		void HandleDamageDealt(AActor* Target, const FGBDamageInfo& Info, float DamageDealt);
144		/** Draws ShownDisplayText into the ammo display render target (its update delegate). */
145		UFUNCTION()
146		void DrawViewModelDisplay(UCanvas* Canvas, int32 Width, int32 Height);
147		/** Sends the Flash value to the weak-point light material, only when it changed. */
148		void SetWeakPointFlash(float Value);
149	
150		UPROPERTY() TArray<TObjectPtr<UStaticMeshComponent>> Parts;
151	
152		/** The art description of the model in use (one constant per model in GBGun.cpp); null without a real viewmodel. */
153		const FGBGunModelArt* ModelArt = nullptr;
154		/** Real viewmodel (only when Definition.ViewModel names a model): body, trigger, magazine, optional energy bar, weak-point light, ammo display. */
155		UPROPERTY() TObjectPtr<UStaticMeshComponent> VMBody = nullptr;
156		UPROPERTY() TObjectPtr<UStaticMeshComponent> VMTrigger = nullptr;
157		UPROPERTY() TObjectPtr<UStaticMeshComponent> VMMagazine = nullptr;
158		UPROPERTY() TObjectPtr<UStaticMeshComponent> VMEnergyBar = nullptr;
159		UPROPERTY() TObjectPtr<UStaticMeshComponent> VMWeakPointLight = nullptr;
160		UPROPERTY() TObjectPtr<UStaticMeshComponent> VMAmmoDisplay = nullptr;
161		/** Muzzle flash: two crossed glowing quads at the muzzle tip, shown briefly on each shot. */
162		UPROPERTY() TObjectPtr<UStaticMeshComponent> MuzzleFlash = nullptr;
163		UPROPERTY() TObjectPtr<UStaticMeshComponent> MuzzleFlashCross = nullptr;
164		UPROPERTY() TObjectPtr<UMaterialInstanceDynamic> MuzzleFlashMID = nullptr;
165		UPROPERTY() TObjectPtr<UMaterialInstanceDynamic> MuzzleFlashCrossMID = nullptr;
166		/** One dynamic instance per material slot of the model parts, so glow and imbue can be set cheaply. */
167		UPROPERTY() TArray<TObjectPtr<UMaterialInstanceDynamic>> ViewModelMIDs;
168		/** Instance of the weak-point light's material (parameter Flash); also in ViewModelMIDs. */
169		UPROPERTY() TObjectPtr<UMaterialInstanceDynamic> ViewModelIndicatorMID = nullptr;
170		/** Instance of the ammo display's material (parameter DisplayTexture); also in ViewModelMIDs. */
171		UPROPERTY() TObjectPtr<UMaterialInstanceDynamic> ViewModelDisplayMID = nullptr;
172		/** Runtime render target the ammo text is drawn into (redrawn only when the text changes). */
173		UPROPERTY() TObjectPtr<UCanvasRenderTarget2D> ViewModelDisplayTarget = nullptr;
174		/** Text last drawn into the render target (the cache that decides whether a redraw is needed). */
175		FString ShownDisplayText;
176		/** Seconds since the last weak-point hit. Negative = the light is off. */
177		float WeakPointFlashElapsed = -1.f;
178		float LastFlashSent = -1.f;
179		FDelegateHandle DamageDealtHandle;
180		bool bViewModel = false;
181		/** Seconds since the last shot started the kick / the muzzle flash. Negative = at rest / hidden. */
182		float KickElapsed = -1.f;
183		float MuzzleFlashElapsed = -1.f;
184		float CurrentKickBackCm = 0.f;
185		/** Pinned reload progress for the smoke run; negative = not pinned. */
186		float ReloadPreview = -1.f;
187		/** The reload pose's contribution to the root right now (location cm, rotation degrees); a cancel blends it to zero. */
188		FVector ReloadPoseLoc = FVector::ZeroVector;
189		FRotator ReloadPoseRot = FRotator::ZeroRotator;
190		FVector ReloadBlendLoc = FVector::ZeroVector;
191		FRotator ReloadBlendRot = FRotator::ZeroRotator;
192		/** Seconds since a cancelled reload started blending to rest. Negative = no blend. */
193		float ReloadBlendElapsed = -1.f;
194		/** Seconds since the last shot started the trigger pull. Negative = the trigger is at rest. */
195		float TriggerPullElapsed = -1.f;
196		/** Last values sent to the model materials (parameters are only set when they change). */
197		bool bHasLastGlow = false;
198		FLinearColor LastGlowColor = FLinearColor::Black;
199		float LastImbueSent = 0.f;
200		EGBElement LastGlowElement = EGBElement::Physical;
201		bool bLastGlowEnchanted = false;
202		bool bEnergyBarBlinking = false;
203	
204		FGBAmmoState Ammo;
205		bool bReloading = false;
206		float ReloadElapsed = 0.f;
207		float ReloadDuration = 0.f;
208	
209		bool bAiming = false;
210		/** 0 = hip, 1 = fully aimed. */
211		float AimAlpha = 0.f;
212		float HipFOV = 90.f;
213	};
